// tools/friction-budget.ts
var g = 9.81;
var m = 70;
var W = m * g;
var h = 0.966;
var omega = Math.sqrt(g / h);
var tau = 1 / omega;
var pMaxX = 0.11;
var PMAX_Z = 0.266;
console.log("\u2550\u2550\u2550\u2550 \u811A\u90E8\u6469\u64E6\u9884\u7B97 \u2550\u2550\u2550\u2550");
console.log("");
console.log(`\u4F53\u91CD            W = m\xB7g = ${m} \xD7 ${g} = ${W.toFixed(1)} N`);
console.log(`\u8D28\u5FC3\u9AD8\u5EA6        h = ${h} m`);
console.log(`LIPM \u5E38\u6570       \u03C9 = \u221A(g/h) = ${omega.toFixed(3)} rad/s   \u03C4 = 1/\u03C9 = ${tau.toFixed(3)} s`);
console.log(`CoP \u884C\u7A0B(\u524D\u540E)  \xB1${pMaxX.toFixed(3)} m     (\u5DE6\u53F3) \xB1${PMAX_Z.toFixed(3)} m`);
console.log("");
var aMax = omega * omega * pMaxX;
console.log("\u2460 \u9759\u6B62\u7AD9\u7ACB\uFF08\u9759\u6001\uFF09");
console.log(`   \u9700\u8981\u7684\u6C34\u5E73\u529B = 0 N\uFF08\u9759\u5E73\u8861\uFF09`);
console.log(`   \u4F46\u6297\u6270\u52A8\u7684\u53EF\u7528\u52A0\u901F\u5EA6 a_max = \u03C9\xB2\xB7p_max = ${aMax.toFixed(3)} m/s\xB2`);
console.log(`   \u21D2 \u9700\u8981\u7684\u6C34\u5E73\u529B\u4E0A\u9650 = m\xB7a_max = ${(m * aMax).toFixed(1)} N`);
console.log("");
console.log("\u2461 \u53EF\u63D0\u4F9B\u7684\u6700\u5927\u6C34\u5E73\u529B F_t,max = \u03BC_eff \xB7 F_n");
console.log("");
console.log("\u03BC_eff  | \u53CC\u811AF_n=W    | \u5355\u811AF_n=W/2  | \u5355\u811A\u80FD\u5426\u63D0\u4F9B m\xB7a_max");
for (const mu of [0.1, 0.2, 0.4, 0.6, 0.8, 1, 1.5, 3, 5.45]) {
  const ftBoth = mu * W;
  const ftOne = mu * (W / 2);
  const need2 = m * aMax;
  const ok = ftOne >= need2 ? "\u2714 \u591F" : `\u2718 \u5DEE ${(need2 / ftOne).toFixed(2)}\xD7`;
  console.log(`${mu.toFixed(2).padStart(6)} | ${ftBoth.toFixed(1).padStart(12)} | ${ftOne.toFixed(1).padStart(12)} | ${ok}`);
}
console.log("");
var need = m * aMax;
var muNeedOne = need / (W / 2);
var muNeedBoth = need / W;
console.log("\u2462 \u53CD\u89E3\uFF08\u5355\u811A\u652F\u6491\u65F6\u8981\u6297\u4F4F\u6700\u5927\u53EF\u63A7\u52A0\u901F\u5EA6\uFF09");
console.log(`   \u9700\u8981 F_t = m\xB7a_max = ${need.toFixed(1)} N`);
console.log(`   \u53CC\u811A\uFF1A\u9700 \u03BC \u2265 ${muNeedBoth.toFixed(3)}`);
console.log(`   \u5355\u811A\uFF1A\u9700 \u03BC \u2265 ${muNeedOne.toFixed(3)}   \u2190 \u5371\u9669\u65F6\u523B`);
console.log("");
var mSwing = 0.08 * m;
var vWalk = 1;
var tSwing = 0.3;
var aSwing = vWalk / (tSwing / 2);
console.log("\u2463 \u884C\u8D70\uFF08\u6446\u52A8\u817F\u52A0\u51CF\u901F\uFF09");
console.log(`   \u6446\u52A8\u817F\u8D28\u91CF \u2248 8% \xD7 ${m} = ${mSwing.toFixed(2)} kg`);
console.log(`   \u5728 ${tSwing} s \u5185\u5230 ${vWalk} m/s \u21D2 a \u2248 ${aSwing.toFixed(2)} m/s\xB2`);
console.log(`   \u9700\u8981\u6C34\u5E73\u529B = ${(mSwing * aSwing).toFixed(1)} N\uFF08\u5F88\u5C0F\uFF0C\u4E0D\u662F\u74F6\u9888\uFF09`);
console.log("");
console.log("\u2550\u2550\u2550\u2550 \u7ED3\u8BBA \u2550\u2550\u2550\u2550");
console.log(`\xB7 **\u5355\u811A\u652F\u6491**\u662F\u6469\u64E6\u7684\u5371\u9669\u65F6\u523B\uFF1A\u9700 \u03BC \u2265 ${muNeedOne.toFixed(2)}\uFF08\u6297\u6700\u5927\u6270\u52A8\uFF09`);
console.log(`\xB7 \u4EC5"\u7AD9\u7740\u4E0D\u6ED1"\u53EA\u9700 \u03BC \u2265 ${0 .toFixed(2)}\uFF08\u9759\u6001\u65E0\u6C34\u5E73\u529B\uFF09`);
console.log(`\xB7 \u5F53\u524D\u8BBE\u7F6E\uFF1A\u978B\u5E95 0.9 + \u5730\u9762 10.0 \u21D2 \u03BC_eff = ${((0.9 + 10) / 2).toFixed(2)}\uFF08\u8FDC\u8D85\u9700\u6C42\uFF0C\u4F46**\u4E0D\u7269\u7406**\uFF09`);
console.log(`\xB7 \u5408\u7406\u76EE\u6807\uFF1A\u03BC_eff \u2248 0.8~1.2\uFF08\u6A61\u80F6-\u6C34\u6CE5\u5B9E\u6D4B 0.8~1.0\uFF09`);
console.log(`  \u21D2 \u5730\u9762\u53D6 \u03BC_ground \u4F7F (0.9 + \u03BC_g)/2 \u2208 [0.8, 1.2] \u21D2 \u03BC_g \u2208 [0.7, 1.5]`);
